describe('Skip-to-Content Link Accessibility', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should navigate to content when skip-to-content link is clicked', () => {
    // Verify skip-to-content link is visible
    cy.get('[data-testid="skip-to-content-link"]').should('be.visible');
    cy.get('[data-testid="skip-to-content-link"]').should('contain', 'Skip to content');

    // Click the skip-to-content link
    cy.get('[data-testid="skip-to-content-link"]').click();

    // Verify navigation to content section
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('contain', 'Welcome to our website');

    // Verify skip-to-content link is hidden after navigation
    cy.get('[data-testid="skip-to-content-link"]').should('not.exist');
  });

  it('should not navigate when skip-to-content link is disabled', () => {
    // Verify skip-to-content link is visible
    cy.get('[data-testid="skip-to-content-link"]').should('be.visible');

    // Verify link is disabled
    cy.get('[data-testid="skip-to-content-link"]').should('have.attr', 'aria-disabled', 'true');

    // Click the disabled skip-to-content link
    cy.get('[data-testid="skip-to-content-link"]').click();

    // Verify navigation does not occur
    cy.get('[data-testid="main-content"]').should('not.exist');

    // Verify skip-to-content link remains visible and disabled
    cy.get('[data-testid="skip-to-content-link"]').should('have.attr', 'aria-disabled', 'true');
  });
});
